export function productT(lang: AppLanguage, key: ProductMessageKey, vars?: Record<string, string | number>): string {
  const raw = PRODUCT_MESSAGES[lang]?.[key] ?? PRODUCT_MESSAGES.en[key] ?? key;
  if (!vars) return raw;
  return Object.entries(vars).reduce(
    (s, [k, v]) => s.split('{' + k + '}').join(String(v)),
    raw,
  );
}
